formulas.expression:
OR(
    /* both blank → never MQL → allow */
    AND(
        ISBLANK({!$Record.Last_Stage_Entry_MQL__c}),
        ISBLANK({!$Record.Last_Stage_Exit_MQL__c})
    ),

    /* entry and exit are exactly the same datetime → stage skipped → allow */
    AND(
        NOT(ISBLANK({!$Record.Last_Stage_Entry_MQL__c})),
        NOT(ISBLANK({!$Record.Last_Stage_Exit_MQL__c})),
        {!$Record.Last_Stage_Entry_MQL__c} = {!$Record.Last_Stage_Exit_MQL__c}
    ),

    /* normal 45‑day rule based on the most recent of the two */
    TODAY() -
    IF(
        ISBLANK({!$Record.Last_Stage_Entry_MQL__c}),
        DATEVALUE({!$Record.Last_Stage_Exit_MQL__c}),
        IF(
            ISBLANK({!$Record.Last_Stage_Exit_MQL__c}),
            DATEVALUE({!$Record.Last_Stage_Entry_MQL__c}),
            IF(
                {!$Record.Last_Stage_Entry_MQL__c} >= {!$Record.Last_Stage_Exit_MQL__c},
                DATEVALUE({!$Record.Last_Stage_Entry_MQL__c}),
                DATEVALUE({!$Record.Last_Stage_Exit_MQL__c})
            )
        )
    ) >= 45
)
